/* Deterministic agreement snapshot renderer. It never reads a live member profile. */
(function(root){
 async function pdf(snapshot,library=root.PDFLib){
  if(!snapshot?.number||!snapshot?.terms?.terms_text||!snapshot?.terms?.privacy_text||!snapshot.signature?.length)throw Error('Volledige ondertekende overeenkomst ontbreekt.');
  const {PDFDocument,StandardFonts,rgb}=library,doc=await PDFDocument.create(),font=await doc.embedFont(StandardFonts.Helvetica),bold=await doc.embedFont(StandardFonts.HelveticaBold),W=595.28,H=841.89,L=48,R=547;
  const logo=await doc.embedPng('data:image/png;base64,');
  const dark=rgb(.08,.09,.10),gold=rgb(.65,.48,.17),grey=rgb(.35,.38,.40);let page,y;
  doc.setTitle('FitMetZorge overeenkomst '+snapshot.number);doc.setAuthor(snapshot.company?.businessName||'FitMetZorge');doc.setCreator('APPFMZ overeenkomst v1');doc.setCreationDate(new Date(snapshot.signedAt));doc.setModificationDate(new Date(snapshot.signedAt));
  const printable=value=>String(value??'').replace(/[\u2010-\u2015]/g,'-').replace(/\u202f/g,' ');
  const width=(s,size=10,f=font)=>{try{return f.widthOfTextAtSize(s,size);}catch{throw Error('Een teken in de gegevens kan niet in het PDF-lettertype worden weergegeven. Controleer de invoer; je concept blijft bewaard.');}};
  function next(){page=doc.addPage([W,H]);if(doc.getPageCount()===1){const scale=160/2868,top=28-892*scale;page.drawImage(logo,{x:L-51*scale,y:H-top-3000*scale,width:3000*scale,height:3000*scale});y=112;}else{y=58;page.drawText('FitMetZorge',{x:L,y:H-y,size:20,font:bold,color:gold});y+=28;}}
  function line(value,size=9,f=font,color=dark){try{f.encodeText(printable(value));}catch{throw Error('Een teken in de gegevens kan niet in het PDF-lettertype worden weergegeven. Controleer de invoer; je concept blijft bewaard.');}if(y+size>760)next();page.drawText(printable(value),{x:L,y:H-y-size,size,font:f,color});y+=size+3;}
  function text(value,size=9,f=font,color=dark){for(const paragraph of printable(value).split(/\r?\n/)){let row='';for(const word of paragraph.split(/\s+/)){if(!word)continue;const candidate=row?row+' '+word:word;if(width(candidate,size,f)<=R-L){row=candidate;continue;}if(row){line(row,size,f,color);row='';}if(width(word,size,f)<=R-L){row=word;continue;}for(const ch of word){if(width(row+ch,size,f)>R-L){line(row,size,f,color);row='';}row+=ch;}}line(row,size,f,color);}}
  function heading(value){y+=8;text(value,12,bold,gold);y+=3;}
  const money=value=>new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR'}).format(value/100),p=snapshot.person,pkg=snapshot.package,s=snapshot.company||{};
  next();heading('ONDERTEKENDE OVEREENKOMST');text(snapshot.number,9,bold);text('Naam: '+[p.firstName,p.insertion,p.lastName].filter(Boolean).join(' '));text('E-mail: '+p.email);text('Telefoon: '+p.phone);text('Geboortedatum: '+p.birthDate);text('Adres: '+[p.street+' '+p.houseNumber,p.postalCode+' '+p.city,p.country].join(', '));
  if(snapshot.duo){const second=snapshot.duo.secondPerson;heading('Duo-overeenkomst');text('Hoofdcontractlid: '+[p.firstName,p.insertion,p.lastName].filter(Boolean).join(' '));text('Tweede deelnemer: '+[second.firstName,second.insertion,second.lastName].filter(Boolean).join(' '));text('Tweede deelnemer e-mail: '+second.email);text('Telefoon: '+second.phone+'; geboortedatum: '+second.birthDate);text('Adres: '+[second.street+' '+second.houseNumber,second.postalCode+' '+second.city,second.country].join(', '));text('Beide deelnemers zijn gekoppeld aan deze ene duo-overeenkomst. De hoofdcontractant ondertekent.');text('Totaal per vier weken: '+money(pkg.cents)+'; per persoon: '+money(snapshot.duo.pricePerPersonCents));text(snapshot.duo.jointSessions+' gezamenlijke trainingen per periode; '+money(Math.round(snapshot.duo.pricePerPersonCents/snapshot.duo.jointSessions))+' per training per persoon.');}

  heading('Pakket en betaling');text(pkg.label,12,bold);text(money(pkg.cents)+' '+(pkg.cycle==='calendar_month'?'per kalendermaand':pkg.cycle==='none'?'eenmalig':'per vier weken (28 dagen)')+' inclusief btw.');if(pkg.priceBasis==='duo')text('Het pakketbedrag geldt per duo.');if(pkg.sessions)text(pkg.sessions+' trainingen per betaalperiode.');if(pkg.cycle==='four_weeks')text('Dertien betaalperiodes per jaar.');text('Ingangsdatum: '+p.startDate);text('Pakketversie: '+pkg.version+' / '+pkg.versionId,8);text('Er is hiermee geen ontvangen betaling geregistreerd.');
  if(snapshot.payment){const pay=snapshot.payment;heading(pay.discountCents?'Eerste periode en korting':'Kosten en eerste periode');text('Eerste periode: '+pay.firstPeriodStart+' t/m '+pay.firstPeriodEnd);if(pay.discountCents){text('Eerste bedrag voor korting: '+money(pay.firstPeriodCents));text('Korting: '+money(pay.discountCents)+'; eerste betaling: '+money(pay.firstPeriodNetCents)+' inclusief btw.',11,bold);text('Korting gedurende de eerste '+pay.discountPeriods+' betaalperiodes, inclusief de eerste periode. Reden: '+pay.discountReason);text('Daarna geldt het volledige pakketbedrag van '+money(pay.baseCents)+' per periode.');}else text('Bedrag eerste periode: '+money(pay.firstPeriodCents)+' inclusief btw.',11,bold);if(pay.firstPeriodCustom)text('Berekening eerste periode: '+pay.firstPeriodReason);text('Verwachte handmatige factuurdatum: '+pay.firstPeriodEnd);text('Start volgende periode: '+(pay.nextPeriodStart||'geen vervolgperiode'));}
  heading('Belangrijkste afspraken');for(const [k,v] of Object.entries(snapshot.terms.summary||{}))text(({notice:'Opzegtermijn',lateCancellation:'Afzeggen',period:'Betaalperiode'}[k]||k)+': '+v);text('Ondertekende voorwaardenversie: '+snapshot.terms.version);text('Marketingtoestemming: '+(p.marketing?'apart gegeven':'niet gegeven'));
  heading('Ondertekening');text('Ondertekenaar: '+snapshot.signer);text('Tijdstip: '+new Date(snapshot.signedAt).toISOString()+' (UTC)');text('De ondertekenaar heeft de gegevens en volledige voorwaarden bekeken.');if(y+125>760)next();page.drawRectangle({x:L,y:H-y-95,width:R-L,height:95,borderWidth:.8,borderColor:grey});for(const stroke of snapshot.signature)for(let i=1;i<stroke.length;i++)page.drawLine({start:{x:L+stroke[i-1][0]*(R-L),y:H-y-stroke[i-1][1]*95},end:{x:L+stroke[i][0]*(R-L),y:H-y-stroke[i][1]*95},thickness:1.8,color:dark});y+=112;text('Inschrijfroute: '+snapshot.route,8);text('Deze elektronische ondertekening wordt niet als gekwalificeerde elektronische handtekening aangeduid.',8);
  if(y+35+[s.businessName,s.address,s.postalCity,s.country,s.email,s.phone,s.chamberNumber,s.vatNumber].filter(Boolean).length*12>760)next();heading('FitMetZorge');for(const value of [s.businessName,s.address,s.postalCity,s.country,s.email,s.phone,s.chamberNumber&&'KVK '+s.chamberNumber,s.vatNumber&&'Btw-id '+s.vatNumber].filter(Boolean))text(value);
  next();heading('Volledige algemene voorwaarden');text('Versie '+snapshot.terms.version,9,bold);text(snapshot.terms.terms_text);
  next();heading('Volledige privacyvoorwaarden');text('Versie '+snapshot.terms.version,9,bold);text(snapshot.terms.privacy_text);text('Bronbewijs / SHA-256: '+snapshot.terms.sha256,8);
  for(const [i,p] of doc.getPages().entries()){if(snapshot.terms.source?.test===true)p.drawText('OEFENOVEREENKOMST - NIET GELDIG',{x:L,y:16,size:10,font:bold,color:rgb(.65,.15,.12)});p.drawLine({start:{x:L,y:43},end:{x:R,y:43},thickness:.5,color:gold});p.drawText(snapshot.number,{x:L,y:29,size:6,font,color:grey});p.drawText((i+1)+' / '+doc.getPageCount(),{x:R-30,y:29,size:8,font,color:grey});}
  return doc.save({useObjectStreams:false});
 }
 const api={pdf};if(typeof module!=='undefined')module.exports=api;else root.FMZMemberDocuments=api;
})(typeof window==='undefined'?globalThis:window);
